_QUOTED_MAM_ATOMS = {
    "1K7:37": "לְכֻלָּֽהְנָֽה׃",
    "Jb4:12": "מֶֽנְהֽוּ׃",
}


def validate_quoted_mam_atoms(rows):
    """Check the full forms quoted in the mtgmtg introduction against its rows."""
    for site, form in _QUOTED_MAM_ATOMS.items():
        matches = [row["r"] for row in rows if row["bcv_short"] == site]
        if matches != [form]:
            raise ValueError(f"mtgmtg quoted atom at {site}: {matches!r} != {[form]!r}")


def explanation_for_path(path_parts):
    assert len(path_parts) == 3, path_parts
    mtg_count_str, sopa_flag, maq_flag = path_parts
    assert mtg_count_str in {"1", "2"}, path_parts
    assert sopa_flag in {"sopa-y", "sopa-n"}, path_parts
    assert maq_flag in {"maq-y", "maq-n"}, path_parts
    mtg_desc = _mtg_count_description(mtg_count_str, sopa_flag)
    sopa_desc = _flag_description("sof pasuq", sopa_flag)
    maq_desc = _flag_description("maqaf", maq_flag)
    return f"that the word contains {mtg_desc}, with {sopa_desc}, and with {maq_desc}"


def _mtg_count_description(mtg_count_str, sopa_flag):
    if sopa_flag == "sopa-y":
        if mtg_count_str == "1":
            return " ".join(
                (
                    "1 Unicode METEG mark in addition to the one serving as",
                    "silluq",
                )
            )
        return " ".join(
            (
                "2 Unicode METEG marks in addition to the one serving as",
                "silluq",
            )
        )
    if mtg_count_str == "1":
        return "1 Unicode METEG mark"
    return "2 Unicode METEG marks"


def _flag_description(feature_name, yn_flag):
    state = "present" if yn_flag.endswith("-y") else "absent"
    return f"{feature_name} {state}"


